#include <iostream>
#include <numeric>

using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long N, A, B;
    if (cin >> N >> A >> B) {
        long long g = gcd(A, B);
        long long m = B / g;
        long long h = A / g;
        if (m <= N && h <= N) {
            cout << (m + h) << "\n";
        } else {
            cout << -1 << "\n";
        }
    }
    return 0;
}

