#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<long long> dp(M + 1, 0);

    for (int i = 0; i < N; ++i) {
        int h, d;
        long long k;
        cin >> h >> k >> d;

        if (d == 1) {
            // 0/1 Knapsack (dosis tinggi, iterasi mundur)
            for (int w = M; w >= h; --w) {
                dp[w] = max(dp[w], dp[w - h] + k);
            }
        } else {
            // Unbounded Knapsack (dosis rendah, iterasi maju)
            for (int w = h; w <= M; ++w) {
                dp[w] = max(dp[w], dp[w - h] + k);
            }
        }
    }

    long long ans = 0;
    for (int w = 0; w <= M; ++w) {
        ans = max(ans, dp[w]);
    }

    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N;
    if (!(cin >> N)) return 0;

    vector<long long> tails; // Untuk mencari LIS

    for (int i = 0; i < N; ++i) {
        long long b;
        cin >> b;
        // Berdasarkan Teorema Dilworth, partisi rantai non-increasing minimal
        // sama dengan panjang Longest Strictly Increasing Subsequence (LIS).
        auto it = lower_bound(tails.begin(), tails.end(), b);
        if (it == tails.end()) {
            tails.push_back(b);
        } else {
            *it = b;
        }
    }

    cout << tails.size() << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

struct Fraction {
    long long num, den;
    bool operator<(const Fraction &other) const {
        return (__int128)num * other.den < (__int128)other.num * den;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long N, M, A, B;
    int Q;
    if (!(cin >> N >> M >> A >> B >> Q)) return 0;

    // Untuk Subtask 1 (N * M <= 10^6):
    vector<Fraction> fracs;
    fracs.reserve(N * M);
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            fracs.push_back({B + j, A + i});
        }
    }

    sort(fracs.begin(), fracs.end());

    for (int q = 0; q < Q; ++q) {
        long long L;
        cin >> L;
        Fraction f = fracs[L - 1];
        long long g = gcd(f.num, f.den);
        cout << (f.num / g) << "/" << (f.den / g) << "\n";
    }

    return 0;
}
